head.script:
// 전역 변수
scwin.CURRENT_PROJECT_ID = "";
scwin.CURRENT_USER_ID = "";
scwin.CURRENT_USER_GROUP_ID = "";

// 페이징 정보
scwin.successPageInfo = { currentPage: 1, pageSize: 10, totalCount: 0, data: [] };
scwin.failPageInfo = { currentPage: 1, pageSize: 10, totalCount: 0, data: [] };
scwin.globalElData = null;
/**
 * 검색 필드 강제 리셋 (마지막에 한 번만 실행)
 */
scwin.forceResetSearchFields = function() {
    try {
        console.log("=== 검색 필드 최종 강제 리셋 ===");

        // 담당자 필드 완전히 비우기
        var assigneeField = $p.getComponentById("inp_searchAssignee");
        if (assigneeField) {
            assigneeField.setValue(""); 
            console.log("담당자 검색 필드 최종 강제 비움");
        }

        // 다른 검색 필드들도 비우기
        var searchFields = [
            { id: "sel_searchTestStatus", method: "setValue" },
            { id: "inp_searchTestCaseName", method: "setValue" },
            { id: "inp_searchTestTarget", method: "setValue" },
            { id: "sel_searchPriority", method: "setValue" },
            { id: "sel_searchTestType", method: "setValue" }
        ];

        searchFields.forEach(function(fieldInfo) {
            var field = $p.getComponentById(fieldInfo.id);
            if (field && field[fieldInfo.method]) {
                field[fieldInfo.method]("");
            }
        });

        console.log("모든 검색 조건 UI 필드 최종 강제 리셋 완료");

    } catch(e) {
        console.error("검색 필드 강제 리셋 실패:", e);
    }
};
/**
 * 페이지 로드 시 초기화
 */
scwin.onpageload = function() {
    console.log("단위테스트 목록 페이지 로드");

    // 즉시 UI 필드를 비움 (다른 코드보다 먼저)
    scwin.immediateResetSearchFields();

    // 초기화
    scwin.initializeData();

    // 사용자 정보 가져오기
    scwin.getCurrentUserInfo();

    // 부모 창에서 프로젝트 ID 가져오기
    scwin.getProjectIdFromParent();

    // 권한에 따른 UI 조정 (값 변경 없이 속성만)
    //setTimeout(function() {
    //    scwin.adjustUIByPermission();
        // UI 조정 후에도 다시 한 번 비움
    //    scwin.immediateResetSearchFields();
    //}, 200);

    // 개발업무 연동 파라미터 처리 (조건부 자동 팝업)
    scwin.handleTaskIdParamWithConditionalPopup();

    // 추가로 여러 번 강제 리셋 (다른 코드들이 값을 설정하는 것 방지)
    setTimeout(function() {
        scwin.immediateResetSearchFields();
    }, 500);

    setTimeout(function() {
        scwin.immediateResetSearchFields();
    }, 1000);

    setTimeout(function() {
        scwin.immediateResetSearchFields();
    }, 1500);

    console.log("페이지 로드 완료");
};

/**
 * 진행중 그리드 더블클릭 이벤트
 */
scwin.processing_grd_oncelldblclick = function(row, col, colId) {
    console.log("진행중 그리드 더블클릭 - 행:", row);

    if (row < 0 || row >= dlt_processingList.getTotalRow()) {
        console.error("유효하지 않은 행 번호:", row);
        return;
    }

    var selectedData = dlt_processingList.getRowJSON(row);
    console.log("선택된 진행중 결함 데이터:", selectedData);

    if (!selectedData || !selectedData.id) {
        console.error("결함ID가 없습니다:", selectedData);
        scwin.showToast("유효하지 않은 데이터입니다.","warning");
        return;
    }

    scwin.openDefectDetailPopup(selectedData);
};
scwin.completed_grd_oncelldblclick = function(row, col, colId) {
    console.log("완료 그리드 더블클릭 - 행:", row);

    if (row < 0 || row >= dlt_completedList.getTotalRow()) {
        console.error("유효하지 않은 행 번호:", row);
        return;
    }

    var selectedData = dlt_completedList.getRowJSON(row);
    console.log("선택된 완료 결함 데이터:", selectedData);

    if (!selectedData || !selectedData.id) {
        console.error("결함ID가 없습니다:", selectedData);
        scwin.showToast("유효하지 않은 데이터입니다.","warning");
        return;
    }

    scwin.openDefectDetailPopup(selectedData);
};

/**
 * 개발업무 연동 파라미터 처리 (조건부 자동 팝업)
 */
scwin.handleTaskIdParamWithConditionalPopup = function() {
    try {
        var developParam = $p.getParameter("tabData");
        if (developParam && developParam.selectedTaskId) {
            console.log("개발업무에서 전달받은 업무ID:", developParam.selectedTaskId);
            console.log("개발업무에서 전달받은 업무명:", developParam.selectedTaskName);
            console.log("개발업무에서 전달받은 flag:", developParam.openRegisterPopup);

            if (developParam.openRegisterPopup === true) { 
                // 개발업무에서 "등록" 버튼을 누른 경우 → 즉시 팝업 자동 열기
                console.log("등록 모드: 백그라운드 목록 조회 후 팝업 자동 열기");

                // UI 필드는 절대 건드리지 않고, 백그라운드 목록만 조회
                scwin.executeBackgroundSearch();

                // 팝업 자동 열기 (약간의 지연 후)
                setTimeout(function() {
                    console.log("개발업무 등록 연동 - 팝업 자동 열기 시작");
                    scwin.openTestRegisterPopupWithTask(
                        developParam.selectedTaskId, 
                        developParam.selectedTaskName || ""
                    );
                }, 300); // 백그라운드 조회가 완료된 후

            } else { 
                // 개발업무에서 업무ID를 클릭한 경우 → 테스트 조회만 (팝업 안 열림)
                console.log("조회 모드: 해당 업무의 테스트만 필터링하여 표시 (팝업 없음)");
                scwin.filterTestsByTask(developParam.selectedTaskId, developParam.selectedTaskName || "");
            } 
        } else {
            // 개발업무에서 온 것이 아닌 경우 → 일반적인 테스트 목록 표시 (팝업 없음)
            console.log("일반 테스트 목록 모드 (팝업 없음)");
            scwin.executeBackgroundSearch();
        }
    } catch (e) {
        console.log("개발 업무ID 파라미터 처리 생략");
        // 파라미터 처리 실패 시에도 일반 목록 표시 (팝업 없음)
        scwin.executeBackgroundSearch();
    }
};
/**
 * 개발업무 연동 파라미터 처리 (목록만 처리, 팝업 열지 않음)
 */
scwin.handleTaskIdParamForListOnly = function() {
    try {
        var developParam = $p.getParameter("tabData");
        if (developParam && developParam.selectedTaskId) {
            console.log("개발업무에서 전달받은 업무ID:", developParam.selectedTaskId);
            console.log("개발업무에서 전달받은 업무명:", developParam.selectedTaskName);
            console.log("개발업무에서 전달받은 flag:", developParam.openRegisterPopup);

            if (developParam.openRegisterPopup === true) { 
                // 개발업무에서 "등록" 버튼을 누른 경우
                console.log("등록 모드 감지: 백그라운드 목록 조회만 수행 (팝업은 버튼 클릭 시에만)");

                // 전역에 등록 모드 정보 저장 (나중에 등록 버튼 클릭 시 사용)
                scwin.pendingTaskRegistration = {
                    taskId: developParam.selectedTaskId,
                    taskName: developParam.selectedTaskName || "",
                    mode: "register"
                };

                // UI 필드는 절대 건드리지 않고, 백그라운드 목록만 조회
                scwin.executeBackgroundSearch();

                console.log("등록 대기 정보 저장:", scwin.pendingTaskRegistration);

            } else { 
                // 개발업무에서 업무ID를 클릭한 경우 → 테스트 조회만 (팝업 안 열림)
                console.log("조회 모드: 해당 업무의 테스트만 필터링하여 표시");
                scwin.filterTestsByTask(developParam.selectedTaskId, developParam.selectedTaskName || "");
            } 
        } else {
            // 개발업무에서 온 것이 아닌 경우 → 일반적인 테스트 목록 표시
            console.log("일반 테스트 목록 모드");
            scwin.executeBackgroundSearch();
        }
    } catch (e) {
        console.log("개발 업무ID 파라미터 처리 생략");
        // 파라미터 처리 실패 시에도 일반 목록 표시
        scwin.executeBackgroundSearch();
    }
};
/**
 * 즉시 검색 필드 초기화 (동기적으로 실행)
 */
scwin.immediateResetSearchFields = function() {
    try {
        console.log("=== 즉시 검색 필드 초기화 ===");

        // 담당자 필드 즉시 비우기
        var assigneeField = $p.getComponentById("inp_searchAssignee");
        if (assigneeField) {
            var beforeValue = assigneeField.getValue();
            assigneeField.setValue(""); 
            var afterValue = assigneeField.getValue();
            console.log("담당자 필드 즉시 초기화:", beforeValue, "→", afterValue);
        }

        // 다른 검색 필드들도 즉시 비우기
        var searchFields = [
            { id: "sel_searchTestStatus", method: "setValue" },
            { id: "inp_searchTestCaseName", method: "setValue" },
            { id: "inp_searchTestTarget", method: "setValue" },
            { id: "sel_searchPriority", method: "setValue" },
            { id: "sel_searchTestType", method: "setValue" }
        ];

        searchFields.forEach(function(fieldInfo) {
            var field = $p.getComponentById(fieldInfo.id);
            if (field && field[fieldInfo.method]) {
                field[fieldInfo.method]("");
            }
        });

        // 데이터맵도 함께 초기화
        dmp_search.set("searchAssignee", "");

        console.log("즉시 검색 필드 초기화 완료");

    } catch(e) {
        console.error("즉시 검색 필드 초기화 실패:", e);
    }
};

/**
 * 데이터 초기화
 */
scwin.initializeData = function() {
    console.log("데이터 초기화 시작");

    // 검색 조건 데이터맵만 초기화 (UI 필드는 건드리지 않음)
    dmp_search.set("pageIndex", "1");
    dmp_search.set("pageSize", "1000");
    dmp_search.set("searchAssignee", ""); // 데이터맵에만 빈 문자열 설정

    // 페이징 정보 초기화
    scwin.successPageInfo = { currentPage: 1, pageSize: 10, totalCount: 0, data: [] };
    scwin.failPageInfo = { currentPage: 1, pageSize: 10, totalCount: 0, data: [] };

    console.log("데이터 초기화 완료 - UI 필드는 건드리지 않음");
};

/**
 * 현재 사용자 정보 가져오기
 */
scwin.getCurrentUserInfo = function() {
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow) {
            var headerFrame = parentWindow.$p.getComponentById("pg_header");
            if (headerFrame && headerFrame.getWindow && headerFrame.getWindow().scwin) {
                var headerScwin = headerFrame.getWindow().scwin;
                var headerDoc = headerFrame.getWindow();

                // 사용자 ID 가져오기
                scwin.CURRENT_USER_ID = headerScwin.USER_ID || "1";

                console.log("=== 사용자 정보 확인 ===");
                console.log("USER_ID:", scwin.CURRENT_USER_ID);

                try {
                    var selectBox = headerDoc.$p.getComponentById("selectBoxProjectName");
                    var selectedPjtId = selectBox ? selectBox.getValue() : null;

                    if (selectedPjtId && headerDoc.dlt_projectName) {
                        var grpIdResult = headerDoc.dlt_projectName.getMatchedColumnData("pjtId", selectedPjtId, "grpId");
                        scwin.CURRENT_USER_GROUP_ID = Array.isArray(grpIdResult) ? grpIdResult[0] : grpIdResult;
                    } else {
                        scwin.CURRENT_USER_GROUP_ID = "2"; // 기본값: 일반 사용자
                    }
                } catch (projectError) {
                    console.error("프로젝트 정보 가져오기 실패:", projectError);
                    scwin.CURRENT_USER_GROUP_ID = "2";
                }

                console.log("GROUP_ID:", scwin.CURRENT_USER_GROUP_ID);
                console.log("isPM:", scwin.isPM());
                console.log("===================");

                return true;
            }
        }

        // 기본값 설정
        scwin.CURRENT_USER_ID = "1";
        scwin.CURRENT_USER_GROUP_ID = "2";
        console.log("기본값으로 사용자 정보 설정");
        return false;

    } catch (e) {
        console.error("사용자 정보 가져오기 실패:", e);
        scwin.CURRENT_USER_ID = "1";
        scwin.CURRENT_USER_GROUP_ID = "2";
        return false;
    }
};

/**
 * PM 권한 여부 확인
 */
scwin.isPM = function() {
    var groupId = scwin.CURRENT_USER_GROUP_ID;
    if (Array.isArray(groupId)) {
        groupId = groupId[0];
    }
    return String(groupId) === "1";
};

/**
 * 부모 창에서 프로젝트 ID 가져오기
 */
scwin.getProjectIdFromParent = function() {
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow && parentWindow.scwin && parentWindow.scwin.SEL_PJT_ID) {
            scwin.CURRENT_PROJECT_ID = parentWindow.scwin.SEL_PJT_ID;
            console.log("현재 선택된 프로젝트 ID:", scwin.CURRENT_PROJECT_ID);

            if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
                scwin.searchUnitTestsByProject();
                scwin.loadStatisticsByProject();
            }
        } else {
            console.log("부모 창에서 프로젝트 ID를 찾을 수 없습니다.");
        }
    } catch (e) {
        console.error("부모 창에서 프로젝트 ID 가져오기 실패:", e);
    }
};

/**
 * 개발업무 연동 파라미터 처리
 */
scwin.handleTaskIdParam = function() {
    try {
        var developParam = $p.getParameter("tabData");
        if (developParam && developParam.selectedTaskId) {
            console.log("개발업무에서 전달받은 업무ID:", developParam.selectedTaskId);
            console.log("개발업무에서 전달받은 flag:", developParam.openRegisterPopup);

            if (developParam.openRegisterPopup === true) { 
                // DevelopPopup.xml에서 "등록" 버튼을 누른 경우에만 팝업 열기
                console.log("등록 모드: 백그라운드 목록 조회 후 팝업 열기");

                // UI 필드는 절대 건드리지 않고, 내부 데이터만 설정
                scwin.executeBackgroundSearch();

                // 팝업 열기
                setTimeout(function() {
                    scwin.openTestRegisterPopupWithTask(developParam.selectedTaskId, developParam.selectedTaskName || "");
                }, 100);

            } else { 
                // DevelopList.xml에서 업무ID를 클릭한 경우 → 테스트 조회만 (팝업 안 열림)
                console.log("조회 모드: 해당 업무의 테스트만 필터링하여 표시");
                scwin.filterTestsByTask(developParam.selectedTaskId, developParam.selectedTaskName || "");
            } 
        } else {
            // 개발업무에서 온 것이 아닌 경우 → 일반적인 테스트 목록 표시
            console.log("일반 테스트 목록 모드");
            scwin.executeBackgroundSearch();
        }
    } catch (e) {
        console.log("개발 업무ID 파라미터 처리 생략");
        // 파라미터 처리 실패 시에도 일반 목록 표시
        scwin.executeBackgroundSearch();
    }
};
/**
 * 일반 사용자를 위한 UI 제한 (수정된 버전 - 검색조건에서 담당자 설정)
 */
scwin.restrictUIForRegularUser = function() {
    try {
        var assigneeField = $p.getComponentById("inp_searchAssignee");
        if (assigneeField) {
            // 일반 사용자는 UI는 자유롭게 두되, 실제 검색 시에는 본인 ID가 적용됨을 안내
            assigneeField.setValue(""); // UI는 비워둠
            assigneeField.setReadOnly(false); // 입력은 가능하게
            assigneeField.setStyle("background-color: white; color: black;");
            assigneeField.setAttribute("placeholder", "담당자명 입력 (본인 테스트만 조회됩니다)");

            console.log("일반 사용자 권한: UI는 자유, 실제 조회 시 권한 제한");
        }
    } catch (e) {
        console.error("일반 사용자 UI 제한 실패:", e);
    }
};

/**
 * 개발업무 연동 파라미터 처리 (수정된 버전)
 */
scwin.handleTaskIdParam = function() {
    try {
        var developParam = $p.getParameter("tabData");
        if (developParam && developParam.selectedTaskId) {
            console.log("개발업무에서 전달받은 업무ID:", developParam.selectedTaskId);
            console.log("개발업무에서 전달받은 flag:", developParam.openRegisterPopup);

            if (developParam.openRegisterPopup) { 
                // DevelopPopup.xml에서 등록 버튼을 누른 경우
                console.log("등록 모드: 백그라운드 목록을 현재 사용자 기준으로 설정");

                // 먼저 검색 조건을 올바르게 설정
                scwin.setBackgroundSearchCondition();

                // 팝업 열기
                setTimeout(function() {
                    scwin.openTestRegisterPopupWithTask(developParam.selectedTaskId, developParam.selectedTaskName || "");
                }, 100);

            } else { 
                // DevelopList.xml에서 업무ID를 클릭한 경우 → 테스트 조회 
                scwin.openTestViewPopupWithTask(developParam.selectedTaskId, developParam.selectedTaskName || "");
            } 
        }
    } catch (e) {
        console.log("개발 업무ID 파라미터 처리 생략");
    }
};

/**
 * 백그라운드 검색 조건 설정 (새 함수)
 */
scwin.setBackgroundSearchCondition = function() {
    console.log("=== 백그라운드 검색 조건 설정 ===");
    console.log("현재 사용자 ID:", scwin.CURRENT_USER_ID);
    console.log("PM 여부:", scwin.isPM());

    // 검색 조건 초기화 (UI는 건드리지 않음)
    dmp_search.setEmptyValue();
    dmp_search.set("pageIndex", "1");
    dmp_search.set("pageSize", "1000");

    // UI 검색 조건은 절대 건드리지 않음! (현재 표시된 상태 그대로 유지)
    console.log("UI 검색 조건은 현재 상태 그대로 유지");

    // 실제 조회 조건에만 권한 적용 (UI와 완전 분리)
    if (!scwin.isPM()) {
        // 일반 사용자: 데이터맵에만 내부적으로 설정 (UI 표시와 무관)
        console.log("일반 사용자 - 데이터맵에만 내부 설정:", scwin.CURRENT_USER_ID);
        // 여기서는 설정하지 않고, 실제 조회 시에만 설정
    } else {
        console.log("PM 사용자 - 모든 데이터 조회");
    }

    // UI 권한 조정 (필드 값은 변경하지 않고 속성만 조정)
    scwin.adjustUIByPermissionWithoutValueChange();

    // 즉시 목록 조회
    if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
        console.log("프로젝트별 조회 실행:", scwin.CURRENT_PROJECT_ID);
        scwin.searchUnitTestsByProject();
    } else {
        console.log("일반 조회 실행");
        scwin.searchUnitTests();
    }

    console.log("=== 백그라운드 검색 조건 설정 완료 ===");
};
/**
 * UI 권한 조정 (필드 값은 변경하지 않고 속성만 조정)
 */
scwin.adjustUIByPermissionWithoutValueChange = function() {
