        console.log("PM 여부:", scwin.isPM());

        var assigneeField = $p.getComponentById("inp_searchAssignee");
        if (assigneeField) {
            // 현재 필드 값 확인 (변경하지 않음)
            var currentValue = assigneeField.getValue();
            console.log("담당자 필드 현재 값:", currentValue, "(변경하지 않음)");

            // 속성만 조정
            assigneeField.setReadOnly(false);
            assigneeField.setStyle("background-color: white; color: black;");

            if (scwin.isPM()) {
                assigneeField.setAttribute("placeholder", "담당자명 입력");
            } else {
                assigneeField.setAttribute("placeholder", "담당자명 입력 (본인 테스트만 조회됩니다)");
            }
        }

        // 다른 검색 필드들 속성 조정 (값은 변경하지 않음)
        var searchFields = [
            "sel_searchTestStatus", 
            "inp_searchTestCaseName", 
            "inp_searchTestTarget",
            "sel_searchPriority",
            "sel_searchTestType"
        ];

        searchFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(false);
            }
        });

        console.log("=== UI 권한 조정 완료 (값 변경 없음) ===");
    } catch (e) {
        console.error("UI 권한 조정 실패:", e);
    }
};

