/**
 * 결함 페이지로 이동하면서 테스트 ID로 검색
 */
scwin.navigateToDefectPageWithTestId = function(testCaseId, testCaseName) {
    console.log("결함 페이지 이동 및 자동 검색 준비:", testCaseId, testCaseName);

    try {
        // 부모 창 접근
        var parentWindow = $p.getParentWindow();
        if (!parentWindow) {
            console.error("부모 창을 찾을 수 없습니다.");
            scwin.showToast("페이지 이동에 실패했습니다.","warning");
            return;
        }

        // 현재 프로젝트 ID 가져오기
        var currentProjectId = scwin.CURRENT_PROJECT_ID || "";

        // 결함 페이지로 전달할 데이터 구성 (UI 표시 안함)
        var defectSearchData = {
            searchTestId: testCaseId,
            searchTestName: testCaseName,
            fromUnitTest: true,
            pjtId: currentProjectId,
            autoSearch: true, // 자동 검색 플래그
            hideSearchField: true // UI 필드에 표시하지 않음 플래그
        };

        console.log("결함 페이지로 전달할 데이터:", defectSearchData);

        // 탭 전환 및 검색 실행
        scwin.switchToDefectTabAndSearch(parentWindow, defectSearchData);

    } catch (e) {
        console.error("결함 페이지 이동 실패:", e);
        scwin.showToast("결함 페이지로 이동하는 중 오류가 발생했습니다.","warning");
    }
};

/**
 * 결함 탭으로 전환하고 자동 검색 실행
 */
scwin.switchToDefectTabAndSearch = function(parentWindow, searchData) {
    try {
        console.log("결함 탭 전환 및 자동 검색 시작");

        // 부모 창의 탭 컨테이너 찾기
        var tabContainer = parentWindow.$p.getComponentById("tac_main") || 
                          parentWindow.$p.getComponentById("tac_content") ||
                          parentWindow.$p.getComponentById("tabContainer");

        if (!tabContainer) {
            console.error("탭 컨테이너를 찾을 수 없습니다.");
            scwin.showToast("결함 페이지를 찾을 수 없습니다.","warning");
            return;
        }

        // 결함 탭 찾기 및 활성화
        var defectTabIndex = -1;
        var tabCount = tabContainer.getTabCount ? tabContainer.getTabCount() : 0;

        for (var i = 0; i < tabCount; i++) {
            var tabLabel = tabContainer.getTabLabel ? tabContainer.getTabLabel(i) : "";
            if (tabLabel && (tabLabel.indexOf("결함") >= 0 || tabLabel.indexOf("defect") >= 0 || tabLabel.indexOf("Defect") >= 0)) {
                defectTabIndex = i;
                break;
            }
        }

        if (defectTabIndex >= 0) {
            console.log("결함 탭 발견, 인덱스:", defectTabIndex);

            // 임시로 검색 데이터 저장 (UI 숨김 플래그 포함)
            parentWindow.tempDefectSearchData = searchData;

            // 탭 활성화
            tabContainer.setSelectedIndex(defectTabIndex);

            // 잠시 후 결함 페이지에 검색 데이터 전달
            setTimeout(function() {
                scwin.sendSearchDataToDefectPageHidden(parentWindow, searchData);
            }, 500);

            console.log("결함 탭 전환 완료 - 자동 검색 예약됨");

        } else {
            console.error("결함 탭을 찾을 수 없습니다.");
           scwin.showToast("결함 관리 탭을 찾을 수 없습니다.","warning");
        }

    } catch (e) {
        console.error("결함 탭 전환 실패:", e);
        scwin.showToast("탭 전환 중 오류가 발생했습니다.","warning");
    }
};

/**
 * 결함 페이지에 검색 데이터 전달 (UI 필드 숨김 모드)
 */
scwin.sendSearchDataToDefectPageHidden = function(parentWindow, searchData) {
    try {
        console.log("결함 페이지에 숨김 모드 검색 데이터 전달:", searchData);

        // 결함 페이지 프레임 찾기
        var defectFrame = parentWindow.$p.getComponentById("wframe_defect") ||
                         parentWindow.$p.getComponentById("defectFrame") ||
                         parentWindow.$p.getComponentById("pg_defect");

        if (defectFrame && defectFrame.getWindow) {
            var defectWindow = defectFrame.getWindow();

            if (defectWindow && defectWindow.scwin) {
                // 결함 페이지의 숨김 모드 검색 조건 설정 함수 호출
                if (typeof defectWindow.scwin.setHiddenSearchConditionFromUnitTest === 'function') {
                    defectWindow.scwin.setHiddenSearchConditionFromUnitTest(searchData);
                } else {
                    // 직접 숨김 모드 검색 조건 설정
                    scwin.setDefectHiddenSearchCondition(defectWindow, searchData);
                }
            } else {
                console.warn("결함 페이지 스크립트를 찾을 수 없습니다.");
            }
        } else {
            console.warn("결함 페이지 프레임을 찾을 수 없습니다.");
        }

    } catch (e) {
        console.error("숨김 모드 검색 데이터 전달 실패:", e);
    }
};

/**
 * 직접 결함 페이지 숨김 모드 검색 조건 설정
 */
scwin.setDefectHiddenSearchCondition = function(defectWindow, searchData) {
    try {
        console.log("직접 결함 페이지 숨김 모드 검색 조건 설정");

        var defectScwin = defectWindow.scwin;

        // 검색 조건 설정 (UI 필드는 건드리지 않음)
        if (defectWindow.dmp_search) {
            // 기존 검색 조건 초기화
            defectWindow.dmp_search.setEmptyValue();
            defectWindow.dmp_search.set("pageIndex", "1");
            defectWindow.dmp_search.set("pageSize", "1000");

            // 테스트 ID로 검색 조건 설정 (데이터맵에만)
            defectWindow.dmp_search.set("testId", searchData.searchTestId);

            // 프로젝트 ID도 설정
            if (searchData.pjtId) {
                defectWindow.dmp_search.set("pjtId", searchData.pjtId);
            }

            // 일반 사용자인 경우 권한 제한 적용
            if (defectScwin && !defectScwin.isPM || (defectScwin.isPM && !defectScwin.isPM())) {
                var currentUserId = defectScwin.CURRENT_USER_ID || "1";
                defectWindow.dmp_search.set("assignee", currentUserId);
            }

            console.log("결함 페이지 숨김 모드 검색 조건 설정 완료:", {
                testId: searchData.searchTestId,
                pjtId: searchData.pjtId,
                hideUI: true
            });
        }

        // UI 필드는 건드리지 않음 (검색 조건 표시 안함)
        console.log("UI 필드는 변경하지 않음 - 숨김 모드");

        // 자동 검색 실행
        if (searchData.autoSearch && defectScwin.btn_search_onclick) {
            setTimeout(function() {
                defectScwin.btn_search_onclick();
                console.log("결함 숨김 모드 자동 검색 실행 완료");

                // 검색 완료 후 결과 알림
                setTimeout(function() {
                    scwin.showHiddenSearchResult(searchData.searchTestId);
                }, 1000);
            }, 200);
        }

    } catch (e) {
        console.error("직접 숨김 모드 검색 조건 설정 실패:", e);
    }
};

/**
 * 숨김 모드 검색 결과 알림
 */
scwin.showHiddenSearchResult = function(testId) {
    try {
        console.log("테스트 ID '" + testId + "'에 대한 결함 검색이 완료되었습니다.");

