    } catch (e) {
        console.error("숨김 모드 검색 결과 알림 실패:", e);
    }
};


/**
 * 직접 결함 탭으로 전환
 */
scwin.switchToDefectTabDirect = function(parentWindow, searchData) {
    try {
        console.log("직접 결함 탭 전환 시도");

        // 부모 창의 탭 컨테이너 찾기
        var tabContainer = parentWindow.$p.getComponentById("tac_main") || 
                          parentWindow.$p.getComponentById("tac_content") ||
                          parentWindow.$p.getComponentById("tabContainer");

        if (!tabContainer) {
            console.error("탭 컨테이너를 찾을 수 없습니다.");
            scwin.showToast("결함 페이지를 찾을 수 없습니다.","warning");
            return;
        }

        // 결함 탭 찾기 및 활성화
        var defectTabIndex = -1;
        var tabCount = tabContainer.getTabCount ? tabContainer.getTabCount() : 0;

        for (var i = 0; i < tabCount; i++) {
            var tabLabel = tabContainer.getTabLabel ? tabContainer.getTabLabel(i) : "";
            if (tabLabel && (tabLabel.indexOf("결함") >= 0 || tabLabel.indexOf("defect") >= 0 || tabLabel.indexOf("Defect") >= 0)) {
                defectTabIndex = i;
                break;
            }
        }

        if (defectTabIndex >= 0) {
            console.log("결함 탭 발견, 인덱스:", defectTabIndex);

            // 임시로 검색 데이터 저장
            parentWindow.tempDefectSearchData = searchData;

            // 탭 활성화
            tabContainer.setSelectedIndex(defectTabIndex);

            // 잠시 후 결함 페이지에 검색 데이터 전달
            setTimeout(function() {
                scwin.sendSearchDataToDefectPage(parentWindow, searchData);
            }, 500);

        } else {
            console.error("결함 탭을 찾을 수 없습니다.");
            scwin.showToast("결함 관리 탭을 찾을 수 없습니다.","warning");
        }

    } catch (e) {
        console.error("직접 탭 전환 실패:", e);
        scwin.showToast("탭 전환 중 오류가 발생했습니다.","warning");
    }
};

/**
 * 결함 페이지에 검색 데이터 전달
 */
scwin.sendSearchDataToDefectPage = function(parentWindow, searchData) {
    try {
        console.log("결함 페이지에 검색 데이터 전달:", searchData);

        // 결함 페이지 프레임 찾기
        var defectFrame = parentWindow.$p.getComponentById("wframe_defect") ||
                         parentWindow.$p.getComponentById("defectFrame") ||
                         parentWindow.$p.getComponentById("pg_defect");

        if (defectFrame && defectFrame.getWindow) {
            var defectWindow = defectFrame.getWindow();

            if (defectWindow && defectWindow.scwin) {
                // 결함 페이지의 검색 조건 설정
                if (typeof defectWindow.scwin.setSearchConditionFromUnitTest === 'function') {
                    defectWindow.scwin.setSearchConditionFromUnitTest(searchData);
                } else {
                    // 직접 검색 조건 설정
                    scwin.setDefectSearchConditionDirect(defectWindow, searchData);
                }
            } else {
                console.warn("결함 페이지 스크립트를 찾을 수 없습니다.");
            }
        } else {
            console.warn("결함 페이지 프레임을 찾을 수 없습니다.");
        }

    } catch (e) {
        console.error("검색 데이터 전달 실패:", e);
    }
};

/**
 * 직접 결함 페이지 검색 조건 설정
 */
scwin.setDefectSearchConditionDirect = function(defectWindow, searchData) {
    try {
        console.log("직접 결함 페이지 검색 조건 설정");

        var defectScwin = defectWindow.scwin;

        // 검색 조건 설정
        if (defectWindow.dmp_search) {
            defectWindow.dmp_search.set("testId", searchData.searchTestId);

            // 프로젝트 ID도 설정
            if (searchData.pjtId) {
                defectWindow.dmp_search.set("pjtId", searchData.pjtId);
            }

            console.log("결함 페이지 검색 조건 설정 완료:", {
                testId: searchData.searchTestId,
                pjtId: searchData.pjtId
            });
        }

        // UI 필드도 업데이트
        var testIdField = defectWindow.$p.getComponentById("inp_searchTestId");
        if (testIdField) {
            testIdField.setValue(searchData.searchTestId);
        }

        // 자동 검색 실행
        if (searchData.autoSearch && defectScwin.btn_search_onclick) {
            setTimeout(function() {
                defectScwin.btn_search_onclick();
                console.log("결함 자동 검색 실행 완료");
            }, 100);
        }

    } catch (e) {
        console.error("직접 검색 조건 설정 실패:", e);
    }
};
/**
 * 업무별 테스트 조회 팝업 열기
 */
scwin.openTestViewPopupWithTask = function(taskId, taskName) {
    console.log("업무별 테스트 조회 팝업 열기:", taskId, taskName);

    dmp_search.set("searchTaskId", taskId);

    if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
        scwin.searchUnitTestsByProject();
    } else {
        scwin.searchUnitTests();
    }

    setTimeout(function() {
        var successCount = dlt_successList.getTotalRow();
        var failCount = dlt_failList.getTotalRow();
        var totalCount = successCount + failCount;

        if (totalCount == 0) {
            var promise = $c.win.confirm(`업무 "${taskName}"에 등록된 테스트가 없습니다.\n\n새로운 테스트를 등록하시겠습니까?`);
            promise.then(function(result) {
                if (result) {
                    scwin.openTestRegisterPopupWithTask(taskId, taskName);
                }
            });
        }
    }, 500);
};

