    if (colId === "testCaseId") {
        console.log("테스트 ID 클릭됨 - 행:", row);

        if (row < 0 || row >= dlt_failList.getTotalRow()) {
            console.error("유효하지 않은 행 번호:", row);
            return;
        }

        var rowData = dlt_failList.getRowJSON(row);
        var testCaseId = rowData.testCaseId;
        var testCaseName = rowData.testCaseName || "";

        if (!testCaseId) {
            console.error("테스트케이스ID가 없습니다:", rowData);
            scwin.showToast("테스트 ID 정보가 없습니다.","info");
            return;
        }

        console.log("결함 탭으로 이동 - 테스트 ID:", testCaseId);
        scwin.navigateToDefectTab(testCaseId, testCaseName);
    }
};

/**
 * 결함 탭으로 이동 (DevelopList의 navigateToTaskTab 방식)
 */
scwin.navigateToDefectTab = function(testCaseId, testCaseName) {
    try {
        console.log("결함 탭 이동 시작:", testCaseId, testCaseName);

        // URL과 타이틀 결정
        let targetUrl = "def/DefectList.xml"; // 또는 실제 결함 페이지 URL
        let tabTitle = "결함 관리";

        // 전달할 탭 데이터 (DevelopList와 동일한 구조)
        const tabData = {
            selectedTestId: testCaseId, // 테스트 ID
            testCaseName: testCaseName,
            fromUnitTest: true, // 단위테스트에서 왔음을 표시
            timestamp: new Date().getTime(),
        };

        console.log("선택된 테스트ID:", testCaseId);

        // 메인페이지의 openTab 함수 호출 (DevelopList와 동일한 방식)
        if ($p.parent() && $p.parent().scwin && $p.parent().scwin.openTab) {
            $p.parent().scwin.openTab(targetUrl, tabTitle, tabData);
        } else {
            console.error("메인페이지의 openTab 함수를 찾을 수 없습니다.");
            scwin.showToast("페이지 이동에 실패했습니다.","warning");
        }

    } catch (error) {
        console.error("결함 화면 이동 중 오류:", error);
        scwin.showToast("화면 이동 중 오류가 발생했습니다.","warning");
    }
};

/**
 * 실패 그리드 더블클릭
 */
scwin.fail_grd_oncelldblclick = function(row, col, colId) {
    console.log("실패그리드 더블클릭 - 행:", row);

    if (row < 0 || row >= dlt_failList.getTotalRow()) {
        console.error("유효하지 않은 행 번호:", row);
        return;
    }

    var selectedData = dlt_failList.getRowJSON(row);
    console.log("선택된 실패 데이터 전체:", selectedData);

    if (!selectedData || !selectedData.testCaseId) {
        console.error("테스트케이스ID가 없습니다:", selectedData);
        scwin.showToast("유효하지 않은 데이터입니다.","info");
        return;
    }

    console.log("팝업으로 전달할 데이터 요약:", {
        testCaseId: selectedData.testCaseId,
        testCaseName: selectedData.testCaseName,
        taskName: selectedData.taskName,
        testStatus: selectedData.testStatus
    });

    scwin.showDetailPopup(selectedData);
};

/**
 * 상세보기 팝업 표시
 */
scwin.showDetailPopup = function(selectedData) {
    console.log("상세보기 팝업 표시:", selectedData);

    if (!selectedData || !selectedData.testCaseId) {
        scwin.showToast("유효하지 않은 데이터입니다.","info");
        return;
    }

    // Test.xml과 완전히 동일한 방식으로 데이터 구성
    var detailData = {
        mode: "view",
        testData: selectedData, // 전체 데이터를 직접 전달
        pjtId: scwin.CURRENT_PROJECT_ID,
        currentUserId: scwin.CURRENT_USER_ID
    };

    console.log("팝업으로 전달할 데이터:", detailData);

    // 데이터 전달을 위한 다중 방법 적용
    // 방법 1: 표준 dataObject 방식
    var jsnPopupData = {
        "type": "json",
        "name": "detailData",
        "data": detailData
    };

    // 방법 2: 부모 창에 임시 저장 (대안)
    try {
        window.tempPopupData = { detailData: detailData };
        console.log("임시 데이터 저장:", window.tempPopupData);
    } catch(e) {
        console.log("임시 데이터 저장 실패:", e);
    }

    var options = {
        id: "unit_test_detail_popup",
        type: "wframePopup",
        width: "1400px",
        height: "900px",
        top: "50px",
        left: "100px",
        popupName: "단위테스트 케이스 상세정보",
        modal: true,
        closeAction: "scwin.testPopup_closeAction",
        dataObject: jsnPopupData
    };

    $p.openPopup("/InsWebApp/ui/test/UnitTestPopup.xml", options);
};



/**
 * 성공 페이지 번호 클릭 이벤트
 */
scwin.pgl_success_onclick = function(idx) {
    console.log("성공 페이지 클릭:", idx);

