/**
 * 검색 조건 초기화
 */
scwin.btn_searchReset_onclick = function(e) {
    console.log("검색 조건 초기화");

    // 데이터맵 완전 초기화
    dmp_search.setEmptyValue();
    dmp_search.set("pageIndex", "1");
    dmp_search.set("pageSize", "1000");

    // UI 필드들 강제로 비우기
    scwin.forceResetSearchFields();

    // 초기화 후 조회
    setTimeout(function() {
        if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
            scwin.searchUnitTestsByProject();
        } else {
            scwin.searchUnitTests();
        }
    }, 100);
};
/**
 * 통계 조회
 */
scwin.loadStatistics = function() {
    console.log("통계 조회 시작");
    $c.sbm.execute($p, sbm_selectUnitTestStatistics);
};

/**
 * 프로젝트별 통계 조회
 */
scwin.loadStatisticsByProject = function() {
    if (!scwin.CURRENT_PROJECT_ID || scwin.CURRENT_PROJECT_ID === "") {
        console.log("프로젝트 ID가 없어 일반 통계 조회를 실행합니다.");
        scwin.loadStatistics();
        return;
    }

    console.log("프로젝트별 통계 조회 시작:", scwin.CURRENT_PROJECT_ID);

    dmp_search.set("pjtId", scwin.CURRENT_PROJECT_ID);
    $c.sbm.execute($p, sbm_selectUnitTestStatisticsByProject);
};

/**
 * 통계 조회 완료
 */
scwin.sbm_selectUnitTestStatistics_submitdone = function(e) {
    console.log("통계 조회 완료", e);

    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        console.error("통계 조회 실패:", elHeader ? elHeader.resMsg : "알 수 없는 오류");
        return;
    }

    dmp_statistics.setJSON(elData);
    console.log("통계 정보:", elData);
};

/**
 * 프로젝트별 통계 조회 완료
 */
scwin.sbm_selectUnitTestStatisticsByProject_submitdone = function(e) {
    console.log("프로젝트별 통계 조회 완료", e);

    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        console.error("프로젝트별 통계 조회 실패:", elHeader ? elHeader.resMsg : "알 수 없는 오류");
        return;
    }

    dmp_statistics.setJSON(elData);
    console.log("프로젝트별 통계 정보:", elData);
};

/**
 * 프로젝트 변경 시 호출되는 함수
 */
scwin.onProjectChange = function(projectId) {
    console.log("프로젝트 변경 이벤트 수신:", projectId);

    scwin.CURRENT_PROJECT_ID = projectId;
    scwin.getCurrentUserInfo();
    scwin.adjustUIByPermission();

    if (projectId && projectId !== "") {
        scwin.searchUnitTestsByProject();
        scwin.loadStatisticsByProject();
    } else {
        scwin.searchUnitTests();
        scwin.loadStatistics();
    }
};

/**
 * 테스트 타입명 변환
 */
scwin.getTestTypeName = function(testType) {
    switch(testType) {
        case "NORMAL": return "정상케이스";
        case "BOUNDARY": return "경계값";
        case "EXCEPTION": return "예외처리";
        case "PERFORMANCE": return "성능";
        default: return testType;
    }
};

/**
 * 우선순위명 변환
 */
scwin.getPriorityName = function(priority) {
    switch(priority) {
        case "HIGH": return "높음";
        case "MEDIUM": return "보통";
        case "LOW": return "낮음";
        default: return priority;
    }
};

/**
 * 우선순위별 배지 스타일 적용
 */
scwin.setPriorityStyle = function () {
    console.log("우선순위 배지 스타일 적용 시작");

    // 성공 그리드 우선순위 스타일 적용
    const successRowCount = dlt_successList.getTotalRow();
    const successColIndex = success_grd.getColumnIndex("priorityName");

    for (let i = 0; i < successRowCount; i++) {
        const priority = dlt_successList.getCellData(i, "priority");
        const priorityStyles = scwin.getPriorityStyleConfig(priority);

        const styles = [
            { type: "cell", rowIndex: i, colIndex: successColIndex, styleName: "background-color", styleValue: priorityStyles.backgroundColor },
            { type: "cell", rowIndex: i, colIndex: successColIndex, styleName: "color", styleValue: priorityStyles.textColor },
            { type: "cell", rowIndex: i, colIndex: successColIndex, styleName: "border-radius", styleValue: "20px" },
            { type: "cell", rowIndex: i, colIndex: successColIndex, styleName: "text-align", styleValue: "center" },
            { type: "cell", rowIndex: i, colIndex: successColIndex, styleName: "font-weight", styleValue: "bold" },
            { type: "cell", rowIndex: i, colIndex: successColIndex, styleName: "font-size", styleValue: "11px" },
            { type: "cell", rowIndex: i, colIndex: successColIndex, styleName: "border", styleValue: "none" },
            { type: "cell", rowIndex: i, colIndex: successColIndex, styleName: "padding", styleValue: "4px 8px" }
        ];

        styles.forEach(style => success_grd.setStyleAll(style));
    }

    // 실패 그리드 우선순위 스타일 적용
    const failRowCount = dlt_failList.getTotalRow();
    const failColIndex = fail_grd.getColumnIndex("priorityName");

    for (let i = 0; i < failRowCount; i++) {
        const priority = dlt_failList.getCellData(i, "priority");
        const priorityStyles = scwin.getPriorityStyleConfig(priority);

        const styles = [
            { type: "cell", rowIndex: i, colIndex: failColIndex, styleName: "background-color", styleValue: priorityStyles.backgroundColor },
            { type: "cell", rowIndex: i, colIndex: failColIndex, styleName: "color", styleValue: priorityStyles.textColor },
            { type: "cell", rowIndex: i, colIndex: failColIndex, styleName: "border-radius", styleValue: "20px" },
            { type: "cell", rowIndex: i, colIndex: failColIndex, styleName: "text-align", styleValue: "center" },
            { type: "cell", rowIndex: i, colIndex: failColIndex, styleName: "font-weight", styleValue: "bold" },
            { type: "cell", rowIndex: i, colIndex: failColIndex, styleName: "font-size", styleValue: "11px" },
            { type: "cell", rowIndex: i, colIndex: failColIndex, styleName: "border", styleValue: "none" },
            { type: "cell", rowIndex: i, colIndex: failColIndex, styleName: "padding", styleValue: "4px 8px" }
        ];

        styles.forEach(style => fail_grd.setStyleAll(style));
    }

    console.log("우선순위 배지 스타일 적용 완료");
};

/**
 * 우선순위별 스타일 설정 반환
 */
scwin.getPriorityStyleConfig = function(priority) {
    let backgroundColor = "#f8f9fa";
    let textColor = "#333333";

    switch (priority) {
        case "HIGH":
            backgroundColor = "#FFE6E6";
            textColor = "#D32F2F";
            break;
        case "MEDIUM":
            backgroundColor = "#FFF8E1";
            textColor = "#F57C00";
            break;
        case "LOW":
            backgroundColor = "#E8F5E8";
            textColor = "#2E7D32";
            break;
        default:
            backgroundColor = "#f8f9fa";
            textColor = "#333333";
    }

    return {
        backgroundColor: backgroundColor,
        textColor: textColor
    };
};

