/**
 * 실패 테스트 엑셀 다운로드
 */
scwin.btn_excel_fail_download_onclick = function (e) {
    var failData = scwin.failPageInfo.data || [];

    if (failData.length === 0) {
        scwin.showToast("다운로드할 실패 데이터가 없습니다.","info");
        return;
    }

    var originalData = dlt_failList.getAllJSON();
    dlt_failList.setJSON(failData);

    var options = {
        fileName: "단위테스트_실패_목록_" + new Date().toISOString().slice(0, 10).replace(/-/g, ""),
        useStyle: true,
        headerFontBold: true,
        bodyFontBold: false,
        type: 1,
        trim: 1,
        processMsg: "엑셀 파일을 생성하고 있습니다...",
        timeout: 60000,
        checkInterval: 1000,
        onSuccessCallback: function () {
            scwin.showToast("실패 테스트 엑셀 파일 다운로드가 완료되었습니다.");
            dlt_failList.setJSON(originalData);
        },
        onFailureCallback: function () {
            scwin.showToast("엑셀 파일 다운로드에 실패했습니다.","warning");
            dlt_failList.setJSON(originalData);
        }
    };

    fail_grd.advancedExcelDownload(options);
};

// 전역 토스트 함수 호출 헬퍼
scwin.showToast = function (message, type = 'success', duration = 3000) {
    // 메인 페이지의 전역 토스트 함수 호출
    try {
        if ($p.top() && $p.top().scwin && $p.top().scwin.showGlobalToast) {
            $p.top().scwin.showGlobalToast(message, type, duration);
        } else {
            // 전역 함수를 찾을 수 없는 경우 기본 alert 사용
            $c.win.alert(message);
        }
    } catch (e) {
        console.error("토스트 표시 중 오류:", e);
        $c.win.alert(message);
    }
};
